template.query:
mutation CreateAttributeWithType($identifier: String!, $name: String!, $description: String, $attributeTypeId: ID!, $tableId: ID!) {
  createAttribute(
    input: {
      identifier: $identifier
      name: $name
      description: $description
      attributeTypeId: $attributeTypeId
      tableId: $tableId
    }
  ) {
    success
    attribute {
      id
      identifier
      name
      description
      attributeType {
        id
        identifier
        name
        dataType
        format
        constraints
        defaultValue
      }
      table {
        id
        identifier
      }
      createdAt
    }
    errors {
      message
      code
    }
  }
}
